def get_total_number_of_sequences(m,n): 
	T=[[0 for i in range(n+1)] for i in range(m+1)] 
	for j in range(1, n+1): 
		for i in range(1, m+1): 
			if j == 1: 
				T[i][j]=1
			else: 
				sum_prev = 0
				for p in range(1, i // 2 + 1):
					sum_prev += T[p][j-1]
				T[i][j] = sum_prev
	total = 0
	for i in range(1, m+1):
		total += T[i][n]
	return total

