		for j in range(n+1):
			if i==0 or j==0:
				T[i][j]=0
			elif i < 1:
				T[i][j]=0
			elif j==1:
				T[i][j]=1
			else:
				T[i][j]=T[i-1][j]+T[i//2][j-1]
	return T[m][n]

